create policy units_select on public.units
  for select to authenticated
  using (
    exists (
      select 1
      from public.residents r
      join public.building_staff s on s.building_id = r.unit_id
      where r.user_id = auth.uid()
        and s.user_id = auth.uid()
    )
    or exists (
      select 1
      from public.building_staff s
      where s.building_id = units.building_id
        and s.user_id = auth.uid()
    )
  );

create policy residents_select on public.residents
  for select to authenticated
  using (
    user_id = auth.uid()
    or exists (
      select 1
      from public.building_staff s
      where s.building_id = (
        select u.building_id from public.units u where u.id = residents.unit_id
      )
        and s.user_id = auth.uid()
    )
  );

create policy building_staff_select on public.building_staff
  for select to authenticated
  using (user_id = auth.uid());

create policy requests_select on public.requests
  for select to authenticated
  using (
    exists (
      select 1
      from public.residents r
      join public.building_staff s on s.building_id = r.unit_id
      where r.user_id = auth.uid()
        and s.user_id = auth.uid()
        and r.unit_id = requests.unit_id
    )
    or exists (
      select 1
      from public.building_staff s
      where s.building_id = (
        select u.building_id from public.units u where u.id = requests.unit_id
      )
        and s.user_id = auth.uid()
    )
  );

create policy requests_insert on public.requests
  for insert to authenticated
  with check (
    created_by = auth.uid()
    and status = 'open'
    and exists (
      select 1
      from public.residents r
      join public.building_staff s on s.building_id = r.unit_id
      where r.user_id = auth.uid()
        and s.user_id = auth.uid()
        and r.unit_id = requests.unit_id
    )
    or exists (
      select 1
      from public.building_staff s
      where s.building_id = (
        select u.building_id from public.units u where u.id = requests.unit_id
      )
        and s.user_id = auth.uid()
    )
  );

create policy requests_update on public.requests
  for update to authenticated
  using (
    exists (
      select 1
      from public.building_staff s
      where s.building_id = (
        select u.building_id from public.units u where u.id = requests.unit_id
      )
        and s.user_id = auth.uid()
    )
  )
  with check (
    exists (
      select 1
      from public.building_staff s
      where s.building_id = (
        select u.building_id from public.units u where u.id = requests.unit_id
      )
        and s.user_id = auth.uid()
    )
    and (
      status in ('open', 'in_progress', 'done')
      and (
        select s.user_id
        from public.building_staff s
        where s.building_id = (
          select u.building_id from public.units u where u.id = requests.unit_id
        )
        and s.user_id = auth.uid()
      )
      is not null
    )
  );

