language plpgsql
as $$
declare
  v_auction public.auctions%rowtype;
  v_out numeric;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update
  skip locked;

  if not found then
    raise exception 'auction % not found', p_auction_id;
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'auction % has ended', p_auction_id;
  end if;

  if v_auction.seller_id = auth.uid() then
    raise exception 'cannot bid on own auction %', p_auction_id;
  end if;

  if v_auction.highest_bid is null then
    if p_amount < v_auction.starting_price then
      raise exception 'bid % below starting price', p_amount;
    end if;
    v_out := p_amount;
  else
    if p_amount < v_auction.highest_bid + v_auction.min_increment then
      raise exception 'bid % below minimum increment', p_amount;
    end if;
    v_out := p_amount;
  end if;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, auth.uid(), p_amount, now());

  update public.auctions
  set highest_bid = v_out,
      highest_bidder = auth.uid()
  where id = p_auction_id;

  return v_out;
end;
$$;
