create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auction public.auctions%rowtype;
  v_highest numeric;
  v_min numeric;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select a.*, coalesce(a.highest_bid, a.starting_price), coalesce(a.min_increment, 10)
  into v_auction, v_highest, v_min
  from public.auctions a
  where a.id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_auction.ends_at < now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.seller_id = auth.uid() then
    raise exception 'cannot bid on own auction';
  end if;

  if p_amount < v_auction.starting_price then
    raise exception 'bid below starting price';
  end if;

  if p_amount < v_highest + v_min then
    raise exception 'bid below minimum increment';
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, auth.uid(), p_amount)
  returning amount into p_amount;

  update public.auctions
  set highest_bid = p_amount, highest_bidder = auth.uid()
  where id = p_auction_id;

  return p_amount;
end;
$$;

